def transform(g):
    from collections import Counter
    h=len(g)
    cnt=Counter(tuple(r) for r in g)
    bg=max(cnt,key=cnt.get)
    nonbg=[i for i in range(h) if tuple(g[i])!=bg]
    for p in range(1,h+1):
        cyc={j:list(g[j]) for j in range(p) if tuple(g[j])!=bg}
        ok=True
        for i in nonbg:
            j=i%p
            if j in cyc:
                if cyc[j]!=list(g[i]): ok=False;break
            else:
                cyc[j]=list(g[i])
        if ok:
            # fill any missing cycle slots with bg
            cyc=[cyc.get(j,list(g[nonbg[0]]) if False else [bg[0]]*len(g[0])) for j in range(p)] if False else [cyc.get(j,None) or list(g[j]) for j in range(p)]
            return [cyc[i%p] for i in range(h)]

